shader.code:
// Infinite Mandala: a kaleidoscopic log-polar zoom tunnel wrapped around an
// iterated "kali" fold (p = |p| / dot(p, p) - k). Everything is 2D, so it
// stays cheap enough for phones and old laptops.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

// Cosine palettes (a + b * cos(2pi * (c * t + d))).
vec3 paletteColor(float t) {
  vec3 a = vec3(0.5);
  vec3 b = vec3(0.5);
  vec3 c = vec3(1.0);
  vec3 d = vec3(0.0, 0.33, 0.67);
  if (palette == 1) {
    c = vec3(1.0, 1.0, 0.5);
    d = vec3(0.8, 0.9, 0.3);
  } else if (palette == 2) {
    d = vec3(0.0, 0.1, 0.2);
  } else if (palette == 3) {
    c = vec3(2.0, 1.0, 0.0);
    d = vec3(0.5, 0.2, 0.25);
  } else if (palette == 4) {
    a = vec3(0.8, 0.5, 0.4);
    b = vec3(0.2, 0.4, 0.2);
    c = vec3(2.0, 1.0, 1.0);
    d = vec3(0.0, 0.25, 0.25);
  } else if (palette == 5) {
    a = vec3(0.5, 0.3, 0.6);
    b = vec3(0.5, 0.4, 0.4);
    d = vec3(0.55, 0.75, 0.95);
  }
  return a + b * cos(TAU * (c * t + d));
}

// Mirrored sawtooth: continuous, so the endless zoom has no seam.
float tri(float x) {
  return abs(fract(x) * 2.0 - 1.0);
}

// Returns (orbit value, trap distance, tunnel depth) at screen point q.
vec3 mandala(vec2 q, float t, float zoomPulse, vec2 k) {
  float r = length(q) + 1e-4;
  float lr = log(r);
  float seg = TAU / float(segments);
  float a = atan(q.y, q.x) + twist * lr + spin * t;
  a = abs(mod(a, seg) - 0.5 * seg);
  float z = (lr - zoomPulse) * density - t * zoomSpeed;
  vec2 p = vec2(a / seg * 2.0, tri(z)) * scale;

  float orbit = 0.0;
  float trap = 1e3;
  for (int i = 0; i < 12; i++) {
    if (i >= iterations) break;
    p = abs(p) / max(dot(p, p), 1e-3) - k;
    orbit += length(p);
    trap = min(trap, abs(p.x * p.y));
  }
  return vec3(orbit / float(iterations), trap, z);
}

vec3 shade(vec3 m, float t, float colorPulse) {
  // Hue follows the tunnel depth, so rainbow rings travel with the zoom.
  float hue = m.x * spread + m.z * rings + hueShift + t * colorSpeed + colorPulse;
  vec3 col = paletteColor(hue);
  float lines = min(glow * 0.015 / (m.y + 0.015), 2.5);
  float body = smoothstep(0.0, 1.0, m.x * 0.35);
  return col * (body * 0.6 + lines);
}

vec3 shader(vec2 uv, float time) {
  float t = time * speed;
  float pulse = beatReact * pow(1.0 - beat, 4.0);
  bool pulseAll = pulseMode == 3;
  float zoomPulse = (pulseMode == 0 || pulseAll) ? pulse * 0.7 : 0.0;
  float colorPulse = (pulseMode == 1 || pulseAll) ? pulse * 0.35 : 0.0;
  vec2 k = morph + ((pulseMode == 2 || pulseAll) ? vec2(pulse * 0.12) : vec2(0.0));

  vec2 q = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0 - center;
  q += warp * 0.2 * sin(q.yx * warpFreq + t * 1.3);

  vec3 col;
  if (aberration > 0.001) {
    // Separate lookups per channel split colors apart towards the edges.
    float s = aberration * 0.04;
    col.r = shade(mandala(q * (1.0 + s), t, zoomPulse, k), t, colorPulse).r;
    col.g = shade(mandala(q, t, zoomPulse, k), t, colorPulse).g;
    col.b = shade(mandala(q * (1.0 - s), t, zoomPulse, k), t, colorPulse).b;
  } else {
    col = shade(mandala(q, t, zoomPulse, k), t, colorPulse);
  }

  if ((pulseMode == 1 || pulseAll)) {
    col *= 1.0 + pulse * 0.6;
  }

  // The log-polar tunnel compresses endless detail into the center; hide it
  // behind a glowing core that breathes with the beat.
  float r = length(q);
  col *= smoothstep(0.02, 0.35, r);
  vec3 coreColor = mix(paletteColor(t * colorSpeed + hueShift + 0.5), vec3(1.0), 0.4);
  col += coreColor * coreGlow * (0.04 + pulse * 0.04) / (r * r * 4.0 + 0.04);
  col = mix(col, col * tint * 1.6, tintAmount);
  col = mix(vec3(dot(col, vec3(0.299, 0.587, 0.114))), col, saturation);
  col = pow(max(col, 0.0), vec3(contrast));
  col *= 1.0 - vignette * smoothstep(0.4, 1.6, length(q));
  col = clamp(col, 0.0, 1.0);
  if (invert) {
    col = 1.0 - col;
  }
  return col;
}
